files.content:
*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  background: #f0f4f8;
  color: #1e293b;
  display: flex;
  justify-content: center;
  align-items: center;
  min-height: 100vh;
  padding: 1rem;
}

.card {
  background: #ffffff;
  border-radius: 1.5rem;
  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.1);
  padding: 2rem;
  max-width: 540px;
  width: 100%;
}

h1 {
  font-size: 1.75rem;
  margin-bottom: 0.25rem;
}

.subtitle {
  font-size: 1rem;
  color: #64748b;
  margin-bottom: 1.5rem;
}

.palette {
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem;
  margin-bottom: 1.5rem;
  align-items: center;
}

.color-btn {
  width: 2.5rem;
  height: 2.5rem;
  border-radius: 50%;
  border: 3px solid transparent;
  cursor: pointer;
  transition: transform 0.1s, border-color 0.2s, box-shadow 0.2s;
  padding: 0;
}

.color-btn:hover {
  transform: scale(1.1);
  box-shadow: 0 0 0 3px rgba(0, 0, 0, 0.1);
}

.color-btn:focus-visible {
  outline: 3px solid #2563eb;
  outline-offset: 2px;
}

.color-btn:active {
  transform: scale(0.95);
}

.color-btn.selected {
  border-color: #1e293b;
  box-shadow: 0 0 0 2px #ffffff, 0 0 0 4px #1e293b;
}

.tool-btn {
  font-size: 1rem;
  padding: 0.5rem 1rem;
  border-radius: 2rem;
  border: 2px solid #cbd5e1;
  background: #f8fafc;
  color: #1e293b;
  cursor: pointer;
  transition: background 0.2s, border-color 0.2s, transform 0.1s;
  font-weight: 500;
}

.tool-btn:hover {
  background: #e2e8f0;
  border-color: #94a3b8;
}

.tool-btn:focus-visible {
  outline: 3px solid #2563eb;
  outline-offset: 2px;
}

.tool-btn:active {
  transform: scale(0.97);
}

.tool-btn.selected {
  background: #1e293b;
  color: #ffffff;
  border-color: #1e293b;
}

.grid {
  display: grid;
  grid-template-columns: repeat(16, 1fr);
  gap: 1px;
  background: #cbd5e1;
  border: 2px solid #cbd5e1;
  border-radius: 0.5rem;
  overflow: hidden;
  margin-bottom: 1.5rem;
  aspect-ratio: 1;
  width: 100%;
}

.cell {
  background: #ffffff;
  cursor: pointer;
  transition: background 0.1s;
  border: none;
  padding: 0;
  min-width: 0;
  min-height: 0;
}

.cell:hover {
  background: #f1f5f9;
}

.cell:focus-visible {
  outline: 2px solid #2563eb;
  outline-offset: -2px;
  z-index: 1;
}

.actions {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 1rem;
  flex-wrap: wrap;
}

.action-btn {
  font-size: 1rem;
  padding: 0.6rem 1.5rem;
  border-radius: 0.75rem;
  border: none;
  background: #e76f51;
  color: #ffffff;
  font-weight: 600;
  cursor: pointer;
  transition: background 0.2s, transform 0.1s;
}

.action-btn:hover {
  background: #d65a3a;
}

.action-btn:focus-visible {
  outline: 3px solid #2563eb;
  outline-offset: 2px;
}

.action-btn:active {
  transform: scale(0.97);
}

.count {
  font-size: 1rem;
  font-weight: 500;
  color: #475569;
}

@media (max-width: 400px) {
  .card {
    padding: 1.25rem;
  }
  h1 {
    font-size: 1.5rem;
  }
  .color-btn {
    width: 2.25rem;
    height: 2.25rem;
  }
}

const grid = document.getElementById('grid');
const countEl = document.getElementById('count');
const eraserBtn = document.getElementById('eraser-btn');
const clearBtn = document.getElementById('clear-btn');
const colorBtns = document.querySelectorAll('.color-btn');

let selectedColor = '#e76f51';
let eraserActive = false;
let paintedCount = 0;

function createGrid() {
  for (let i = 0; i < 256; i++) {
    const cell = document.createElement('button');
    cell.className = 'cell';
    cell.setAttribute('role', 'gridcell');
    cell.setAttribute('aria-label', `Cell ${i + 1}`);
    cell.dataset.painted = 'false';
    cell.addEventListener('click', () => paintCell(cell));
    grid.appendChild(cell);
  }
}

function paintCell(cell) {
  const wasPainted = cell.dataset.painted === 'true';
  if (eraserActive) {
    cell.style.backgroundColor = '#ffffff';
    if (wasPainted) {
      cell.dataset.painted = 'false';
      paintedCount--;
    }
  } else {
    cell.style.backgroundColor = selectedColor;
    if (!wasPainted) {
      cell.dataset.painted = 'true';
      paintedCount++;
    }
  }
  updateCount();
}

function updateCount() {
  countEl.textContent = `Painted: ${paintedCount}`;
}

function selectColor(btn) {
  colorBtns.forEach(b => {
    b.classList.remove('selected');
    b.setAttribute('aria-pressed', 'false');
  });
  btn.classList.add('selected');
  btn.setAttribute('aria-pressed', 'true');
  selectedColor = btn.dataset.color;
  eraserActive = false;
  eraserBtn.classList.remove('selected');
  eraserBtn.setAttribute('aria-pressed', 'false');
}

function toggleEraser() {
  eraserActive = !eraserActive;
  eraserBtn.classList.toggle('selected', eraserActive);
  eraserBtn.setAttribute('aria-pressed', eraserActive ? 'true' : 'false');
  if (eraserActive) {
    colorBtns.forEach(b => {
      b.classList.remove('selected');
      b.setAttribute('aria-pressed', 'false');
    });
  } else {
    const first = colorBtns[0];
    first.classList.add('selected');
    first.setAttribute('aria-pressed', 'true');
    selectedColor = first.dataset.color;
  }
}

function clearGrid() {
  document.querySelectorAll('.cell').forEach(cell => {
    cell.style.backgroundColor = '#ffffff';
    cell.dataset.painted = 'false';
  });
  paintedCount = 0;
  updateCount();
}

colorBtns.forEach(btn => {
  btn.addEventListener('click', () => selectColor(btn));
});

eraserBtn.addEventListener('click', toggleEraser);
clearBtn.addEventListener('click', clearGrid);

createGrid();
updateCount();
